def scan_areas(track: dict) -> dict[str, str]:
    return {
        "filename": track["filename"],
        "Track": track["track"],
        "STYLE": track["sections"].get("STYLE", ""),
        "LYRICS": track["sections"].get("LYRICS", ""),
    }


def lyric_content_lines(track: dict) -> list[tuple[int, str]]:
    lines = []
    for index, raw_line in enumerate(track["sections"].get("LYRICS", "").splitlines(), start=1):
        line = raw_line.strip()
        if line and not line.startswith("["):
            lines.append((index, line))
    return lines


def lyric_code_switch_hits(track: dict) -> list[dict]:
    return [
        {"file": track["filename"], "line": number, "evidence": line}
        for number, line in lyric_content_lines(track)
        if LYRIC_CODE_SWITCH_PATTERN.search(line)
    ]


def add_finding(findings: list[dict], code: str, message: str, track: dict | None = None, **extra: object) -> None:
    item = {"code": code, "message": message}
    if track:
        item.update({"file": track["filename"], "order": f"{track['order']:02d}" if track.get("order") else None})

